class Learner {
    String name; int xp;
    Learner(String name, int xp) { this.name = name; this.xp = xp; }
}
Learner learner = new Learner("Ama", 120);
System.out.println(learner.name);

class Lesson {
    String title;
    Lesson(String title) { this.title = title; }
    String label() { return "Lesson: " + title; }
}
System.out.println(new Lesson("Loops").label());

class Progress {
    int done, total;
    Progress(int done, int total) { this.done = done; this.total = total; }
    double percent() { return total == 0 ? 0 : done * 100.0 / total; }
}
System.out.println(new Progress(4, 10).percent());
